// === NAME - DESCRIPTION: Addition Rule for a Union Probability - compute P(A OR B) by subtracting the overlap, and recognize why adding the two rates alone overcounts ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
$pa = rand(30,55);
$pb = rand(25,50);
$pab = rand(8, min($pa,$pb) - 12);
$punion = $pa + $pb - $pab;
$pover = $pa + $pb;

$contexts = array(
  "a randomly chosen student at a large high school",
  "a randomly chosen adult in a city survey",
  "a randomly chosen customer at a hardware store",
  "a randomly chosen employee at a company"
);
$ci = rand(0, 3);
$who = $contexts[$ci];

$events = array(
  array("owns a dog", "owns a cat"),
  array("has a gym membership", "has a streaming subscription"),
  array("bought paint", "bought lumber"),
  array("takes the bus to work", "packs a lunch")
);
$ei = rand(0, 3);
$evA = $events[$ei][0];
$evB = $events[$ei][1];

$anstypes = array("number", "number", "choices");

$answer[0] = $pover;
$answer[1] = $punion;
$answer[2] = 1;

$questions[2] = array(
  "Because some people are counted in both groups, so those people get counted twice.",
  "Because the two percentages do not add up to 100%.",
  "Because the survey did not include everyone in the population.",
  "Because the two events are independent of one another."
);

// === QUESTION TEXT ===
<p>A survey of $who records two characteristics. The results are:</p>
<ul>
<li>P($evA) = $pa%</li>
<li>P($evB) = $pb%</li>
<li>P(both $evA and $evB) = $pab%</li>
</ul>

<p>(a) A student computes P($evA or $evB) by adding the two percentages: $pa% + $pb%. What value does this give? Give your answer as a percent, without the % sign.</p>
<p>Answer: $answerbox[0]</p>

<p>(b) Use the Addition Rule to find the correct value of P($evA or $evB). Give your answer as a percent, without the % sign.</p>
<p>Answer: $answerbox[1]</p>

<p>(c) Why does simply adding the two percentages overcount?</p>
<p>$answerbox[2]</p>

// === ANSWER ===
$solutionguide = '<p><strong>Step 1 — Add the two rates.</strong> Adding gives ' . $pa . '% + ' . $pb . '% = ' . $pover . '%. This is too large.</p>
<p><strong>Step 2 — Subtract the overlap.</strong> The people who are in <em>both</em> groups were counted once in each rate, so they were counted twice. The Addition Rule removes the double count:</p>
<p>P(A or B) = P(A) + P(B) - P(A and B) = ' . $pa . '% + ' . $pb . '% - ' . $pab . '% = ' . $punion . '%</p>
<p><strong>Step 3 — Interpret.</strong> The plain sum overcounts because the ' . $pab . '% who are in both groups are included in both of the first two percentages. Subtracting P(A and B) once corrects for that double counting.</p>
<p><strong>Answer:</strong> (a) ' . $pover . '%; (b) ' . $punion . '%; (c) the overlap is counted twice.</p>';

// === NAME - DESCRIPTION: Function or Not? Determine whether each relation (table, set of ordered pairs, or mapping) represents a function ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
$type = rand(0,2);

// Build a relation that is or is not a function, and record the truth.
$isFunc = rand(0,1);

if ($type == 0) {
  // Table of x -> y
  $xs = array(1,2,3,4);
  if ($isFunc == 1) {
    // each x distinct, y arbitrary
    $ys = array();
    for ($i=0;$i<4;$i++) { $ys[$i] = rand(1,9); }
  } else {
    // repeat one x with two different y values
    $ys = array();
    for ($i=0;$i<4;$i++) { $ys[$i] = rand(1,9); }
    $rep = rand(0,3);
    $other = ($rep + 1 + rand(0,2)) % 4;
    while ($ys[$other] == $ys[$rep]) { $ys[$other] = rand(1,9); }
    $xs[$other] = $xs[$rep];
  }
  $relText = "<table style='border-collapse:collapse;margin:8px 0;'>";
  $relText .= "<tr><th style='border:1px solid #444;padding:4px 12px;'>x</th>";
  for ($i=0;$i<4;$i++) { $relText .= "<td style='border:1px solid #444;padding:4px 12px;text-align:center;'>".$xs[$i]."</td>"; }
  $relText .= "</tr><tr><th style='border:1px solid #444;padding:4px 12px;'>y</th>";
  for ($i=0;$i<4;$i++) { $relText .= "<td style='border:1px solid #444;padding:4px 12px;text-align:center;'>".$ys[$i]."</td>"; }
  $relText .= "</tr></table>";
} else if ($type == 1) {
  // Set of ordered pairs
  $xs = array(1,2,3,4);
  $ys = array();
  for ($i=0;$i<4;$i++) { $ys[$i] = rand(1,9); }
  if ($isFunc == 0) {
    $rep = rand(0,3);
    $other = ($rep + 1 + rand(0,2)) % 4;
    while ($ys[$other] == $ys[$rep]) { $ys[$other] = rand(1,9); }
    $xs[$other] = $xs[$rep];
  }
  $pairs = array();
  for ($i=0;$i<4;$i++) { $pairs[$i] = "(".$xs[$i].", ".$ys[$i].")"; }
  $relText = "\\{ " . $pairs[0] . ", " . $pairs[1] . ", " . $pairs[2] . ", " . $pairs[3] . " \\}";
} else {
  // Mapping diagram described in words
  $xs = array(1,2,3,4);
  $ys = array();
  for ($i=0;$i<4;$i++) { $ys[$i] = rand(1,9); }
  if ($isFunc == 0) {
    $rep = rand(0,3);
    $other = ($rep + 1 + rand(0,2)) % 4;
    while ($ys[$other] == $ys[$rep]) { $ys[$other] = rand(1,9); }
    $xs[$other] = $xs[$rep];
  }
  $pairs = array();
  for ($i=0;$i<4;$i++) { $pairs[$i] = $xs[$i] . " &rarr; " . $ys[$i]; }
  $relText = $pairs[0] . ", " . $pairs[1] . ", " . $pairs[2] . ", " . $pairs[3];
}

$questions[0] = array("Yes, it is a function", "No, it is not a function");
$questions[1] = array("Yes, it is a function", "No, it is not a function");
$questions[2] = array("Yes, it is a function", "No, it is not a function");

if ($isFunc == 1) {
  $answer[0] = 0; $answer[1] = 0; $answer[2] = 0;
} else {
  $answer[0] = 1; $answer[1] = 1; $answer[2] = 1;
}

$anstypes = "choices,choices,choices";
$noshuffle = "questions";

// === QUESTION TEXT ===
<p>Determine whether the relationship shown below represents a function.</p>

<p>$relText</p>

<p>Is this relationship a function?</p>
<p>$answerbox[0]</p>

<p>Now consider a second relationship: $\{ (1, 2), (2, 3), (3, 4), (4, 5) \}$</p>
<p>Is this relationship a function?</p>
<p>$answerbox[1]</p>

<p>Finally, consider the relationship $1 \to 5,\ 2 \to 6,\ 3 \to 7,\ 4 \to 8$.</p>
<p>Is this relationship a function?</p>
<p>$answerbox[2]</p>

// === ANSWER ===
$solutionguide = 'A relationship is a function when every input (x-value) is paired with exactly one output (y-value). If any input repeats with two different outputs, the relationship is not a function.';

// === NAME - DESCRIPTION:  ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
// Build a 2x2 table with random row and column totals, then randomize the
// top-left cell so that all four observed counts are positive integers.
$row1 = rand(40, 90);
$row2 = rand(40, 90);
$col1 = rand(40, 90);
$col2 = rand(40, 90);

// Grand total must be consistent: row1 + row2 = col1 + col2.
// Pick col1 so that col2 = row1 + row2 - col1 is also in a sensible range.
$grand = $row1 + $row2;
$col1 = rand(35, $grand - 35);
$col2 = $grand - $col1;

// Observed top-left cell: must leave every cell positive.
$lo = max(5, $row1 - $col2 + 1, $col1 - $row2 + 1);
$hi = min($row1 - 5, $col1 - 5);
if ($hi < $lo) { $hi = $lo; }
$a = rand($lo, $hi);
$b = $row1 - $a;
$c = $col1 - $a;
$d = $row2 - $c;

// Expected counts: E = (row total * col total) / grand total
$e11 = $row1 * $col1 / $grand;
$e12 = $row1 * $col2 / $grand;
$e21 = $row2 * $col1 / $grand;
$e22 = $row2 * $col2 / $grand;

// Round to two decimals for display and for the key
$e11r = round($e11, 2);
$e12r = round($e12, 2);
$e21r = round($e21, 2);
$e22r = round($e22, 2);

$anstypes = "number,number,number";
$answer[0] = $e11r;
$answer[1] = $e12r;
$answer[2] = $e21r;
$abstolerance[0] = 0.02;
$abstolerance[1] = 0.02;
$abstolerance[2] = 0.02;

// === QUESTION TEXT ===
<p>A random sample of <b>$grand</b> adults was classified by two variables: whether they
exercise regularly (Yes / No) and whether they report having high blood pressure
(Yes / No). The observed counts are shown in the table below.</p>

<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse; text-align:center;">
  <tr>
    <th></th>
    <th>High BP: Yes</th>
    <th>High BP: No</th>
    <th>Row Total</th>
  </tr>
  <tr>
    <th>Exercise: Yes</th>
    <td>$a</td>
    <td>$b</td>
    <td>$row1</td>
  </tr>
  <tr>
    <th>Exercise: No</th>
    <td>$c</td>
    <td>$d</td>
    <td>$row2</td>
  </tr>
  <tr>
    <th>Column Total</th>
    <td>$col1</td>
    <td>$col2</td>
    <td>$grand</td>
  </tr>
</table>

<p>We wish to carry out a chi-square test of independence. Under the null hypothesis of
independence, the expected count in each cell is</p>

<p style="text-align:center;">expected count = (row total &times; column total) / grand total.</p>

<p>Compute the expected counts for the three cells below. Round each answer to two decimal places.</p>

<p>(a) Exercise: Yes and High BP: Yes &nbsp; $answerbox[0]</p>
<p>(b) Exercise: Yes and High BP: No &nbsp; $answerbox[1]</p>
<p>(c) Exercise: No and High BP: Yes &nbsp; $answerbox[2]</p>

// === ANSWER ===
$solutionguide = '<p>Under the null hypothesis of independence, the expected count in a cell is</p>
<p style="text-align:center;">E = (row total &times; column total) / grand total.</p>
<p>Here the grand total is ' . $grand . '.</p>
<p><b>Step 1 &mdash; Exercise: Yes and High BP: Yes.</b>
Row total = ' . $row1 . ', column total = ' . $col1 . ', so
E = (' . $row1 . ' &times; ' . $col1 . ') / ' . $grand . ' = ' . $e11r . '.</p>
<p><b>Step 2 &mdash; Exercise: Yes and High BP: No.</b>
Row total = ' . $row1 . ', column total = ' . $col2 . ', so
E = (' . $row1 . ' &times; ' . $col2 . ') / ' . $grand . ' = ' . $e12r . '.</p>
<p><b>Step 3 &mdash; Exercise: No and High BP: Yes.</b>
Row total = ' . $row2 . ', column total = ' . $col1 . ', so
E = (' . $row2 . ' &times; ' . $col1 . ') / ' . $grand . ' = ' . $e21r . '.</p>
<p>Answer: (a) ' . $e11r . ', (b) ' . $e12r . ', (c) ' . $e21r . '.</p>
<p>Note that the fourth cell could be found the same way, or by subtraction:
' . $grand . ' &minus; ' . $e11r . ' &minus; ' . $e12r . ' &minus; ' . $e21r . ' = ' . $e22r . '.</p>';

// === NAME - DESCRIPTION: Reading a Study - Classify a described study as observational or experimental, name a plausible source of bias or confounding, and state what conclusion is and is not justified ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
$scenarios = array();
$scenarios[0] = array(
  "text" => "A school nurse wants to know whether students who eat breakfast earn higher grades. She records, for every student in the school, whether the student usually eats breakfast and each student's grade point average.",
  "kind" => "observational",
  "conf" => "Students who eat breakfast may also get more sleep, have more stable home routines, or come from families with more resources, and any of these could raise grades on its own.",
  "yes" => "Students who usually eat breakfast tend to have higher grade point averages than students who do not.",
  "no" => "Eating breakfast causes higher grades."
);
$scenarios[1] = array(
  "text" => "A gym teacher randomly assigns 60 volunteers to one of two groups. One group walks for 20 minutes before class each day for a month; the other sits quietly for the same 20 minutes. At the end of the month she measures each student's resting heart rate.",
  "kind" => "experimental",
  "conf" => "Even with random assignment, students know which group they are in, so those who walk may also change other habits, and the volunteers may not represent all students at the school.",
  "yes" => "For students like these volunteers, walking for 20 minutes before class caused a change in resting heart rate, on average.",
  "no" => "Walking for 20 minutes before class will lower the resting heart rate of every student at the school."
);
$scenarios[2] = array(
  "text" => "A city health department compares residents who live within 200 meters of a new bike path with residents who live farther away, and finds that the near group reports more minutes of weekly exercise.",
  "kind" => "observational",
  "conf" => "People who choose to live near a bike path may already be more active, and neighborhoods near new paths may differ in income, safety, or walkability.",
  "yes" => "Residents living near the bike path reported more weekly exercise than residents living farther away.",
  "no" => "Building the bike path caused residents to exercise more."
);
$scenarios[3] = array(
  "text" => "A company randomly assigns 200 employees to a four-day work week and 200 to a five-day work week for three months, then compares the two groups on a standardized measure of reported stress.",
  "kind" => "experimental",
  "conf" => "Employees know their own schedule, so expectations and morale may differ between groups, and the three-month period may not reflect long-term effects.",
  "yes" => "For employees like these, a four-day work week caused a change in reported stress, on average.",
  "no" => "A four-day work week will reduce stress for every worker in every company."
);
$scenarios[4] = array(
  "text" => "A researcher surveys 500 adults who shop at a particular farmers market and finds that those who report buying organic produce also report fewer doctor visits per year.",
  "kind" => "observational",
  "conf" => "Shoppers at a farmers market are not representative of all adults, and those who buy organic produce may differ in income, diet, and overall health habits.",
  "yes" => "Among these shoppers, those who reported buying organic produce also reported fewer doctor visits.",
  "no" => "Buying organic produce reduces the number of doctor visits a person makes."
);
$scenarios[5] = array(
  "text" => "To test a new fertilizer, an agricultural station randomly assigns 40 identical plots of land to receive the new fertilizer and 40 to receive the standard fertilizer. At harvest, the station weighs the yield from each plot.",
  "kind" => "experimental",
  "conf" => "The plots are identical and randomly assigned, but the station knows which plots got which fertilizer, so measurement or handling could differ slightly between groups.",
  "yes" => "For plots like these, the new fertilizer caused a change in yield, on average.",
  "no" => "The new fertilizer will increase yield on every farm in the country."
);

$idx = rand(0, 5);
$scenario = $scenarios[$idx];

$anstypes = "choices,string,string,string";

$questions[0] = array(
  "an observational study",
  "an experiment"
);
$answer[0] = ($scenario["kind"] == "observational") ? 0 : 1;

$answer[1] = $scenario["conf"];

$answer[2] = $scenario["yes"];

$answer[3] = $scenario["no"];

$strflags[1] = "ignore_case,trim_whitespace";
$strflags[2] = "ignore_case,trim_whitespace";
$strflags[3] = "ignore_case,trim_whitespace";

$showallparts = 1;

// === QUESTION TEXT ===
<p>Read the description of a study below, then answer the questions that follow.</p>

<p><b>Study:</b> $scenario[text]</p>

<p><b>(a)</b> Is this study an observational study or an experiment? $answerbox[0]</p>

<p><b>(b)</b> Name one plausible source of bias or confounding in this study, and explain briefly why it could affect the results. $answerbox[1]</p>

<p><b>(c)</b> State one conclusion that <i>is</i> justified by this study. $answerbox[2]</p>

<p><b>(d)</b> State one conclusion that is <i>not</i> justified by this study. $answerbox[3]</p>

/// [TEXT]
<p><b>(a)</b> Is this study an observational study or an experiment? $answerbox[0]</p>

<p><b>(b)</b> Name one plausible source of bias or confounding in this study, and explain briefly why it could affect the results. $answerbox[1]</p>

<p><b>(c)</b> State one conclusion that <i>is</i> justified by this study. $answerbox[2]</p>

<p><b>(d)</b> State one conclusion that is <i>not</i> justified by this study. $answerbox[3]</p>

// === ANSWER ===
$solutionguide = '<p><b>Step 1 &mdash; Classify the study.</b> This is ' . (($scenario["kind"] == "observational") ? 'an <b>observational study</b>: the researcher did not assign the treatment, only recorded what was already true.' : 'an <b>experiment</b>: the researcher randomly assigned which subjects received which treatment.') . '</p>';

$solutionguide .= '<p><b>Step 2 &mdash; Identify a source of bias or confounding.</b> ' . $scenario["conf"] . '</p>';

$solutionguide .= '<p><b>Step 3 &mdash; State what is justified.</b> ' . $scenario["yes"] . '</p>';

$solutionguide .= '<p><b>Step 4 &mdash; State what is not justified.</b> ' . $scenario["no"] . '</p>';

$solutionguide .= '<p><b>Answer:</b> ' . (($scenario["kind"] == "observational") ? 'Observational study' : 'Experiment') . '. A plausible source of bias or confounding is described above. The justified conclusion is a statement of association (or, for an experiment, a cause-and-effect conclusion limited to subjects like those studied); the unjustified conclusion is stated above.</p>';

// === NAME - DESCRIPTION:  ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
$cats = array("Freshman", "Sophomore", "Junior", "Senior");
$ncat = 4;

// Total 200 so every count is 2 * percent and percentages are exact integers.
$total = 200;

$c0 = 2 * rand(12, 22);
$c1 = 2 * rand(12, 22);
$c2 = 2 * rand(12, 22);
$c3 = $total - $c0 - $c1 - $c2;
$guard = 0;
while (($c3 < 24 || $c3 > 44) && $guard < 200) {
  $c0 = 2 * rand(12, 22);
  $c1 = 2 * rand(12, 22);
  $c2 = 2 * rand(12, 22);
  $c3 = $total - $c0 - $c1 - $c2;
  $guard = $guard + 1;
}
$counts = array($c0, $c1, $c2, $c3);

$pcts = array();
for ($i = 0; $i < $ncat; $i++) {
  $pcts[$i] = $counts[$i] / 2;
}

$pick = rand(0, 3);
$pickName = $cats[$pick];
$pickCount = $counts[$pick];
$pickPct = $pcts[$pick];

$maxCount = 0;
for ($i = 0; $i < $ncat; $i++) {
  if ($counts[$i] > $maxCount) { $maxCount = $counts[$i]; }
}
$axisTop = 10 * (floor($maxCount / 10) + 1);

$svgW = 460;
$svgH = 320;
$padL = 60;
$padB = 50;
$padT = 20;
$plotW = $svgW - $padL - 20;
$plotH = $svgH - $padB - $padT;
$barW = 60;
$gap = ($plotW - $ncat * $barW) / ($ncat + 1);

$svg = '<svg xmlns="http://www.w3.org/2000/svg" width="' . $svgW . '" height="' . $svgH . '" viewBox="0 0 ' . $svgW . ' ' . $svgH . '">';
$svg .= '<rect x="0" y="0" width="' . $svgW . '" height="' . $svgH . '" fill="#ffffff"/>';

for ($g = 0; $g <= $axisTop; $g = $g + 10) {
  $y = $padT + $plotH - ($g / $axisTop) * $plotH;
  $svg .= '<line x1="' . $padL . '" y1="' . round($y, 1) . '" x2="' . ($padL + $plotW) . '" y2="' . round($y, 1) . '" stroke="#cccccc" stroke-width="1"/>';
  $svg .= '<text x="' . ($padL - 8) . '" y="' . round($y + 4, 1) . '" font-size="12" text-anchor="end" fill="#333333">' . $g . '</text>';
}

for ($i = 0; $i < $ncat; $i++) {
  $x = $padL + $gap + $i * ($barW + $gap);
  $h = ($counts[$i] / $axisTop) * $plotH;
  $y = $padT + $plotH - $h;
  $svg .= '<rect x="' . round($x, 1) . '" y="' . round($y, 1) . '" width="' . $barW . '" height="' . round($h, 1) . '" fill="#4a7ebb"/>';
  $svg .= '<text x="' . round($x + $barW / 2, 1) . '" y="' . round($y - 6, 1) . '" font-size="12" text-anchor="middle" fill="#222222">' . $counts[$i] . '</text>';
  $svg .= '<text x="' . round($x + $barW / 2, 1) . '" y="' . ($padT + $plotH + 18) . '" font-size="12" text-anchor="middle" fill="#222222">' . $cats[$i] . '</text>';
}

$svg .= '<line x1="' . $padL . '" y1="' . $padT . '" x2="' . $padL . '" y2="' . ($padT + $plotH) . '" stroke="#333333" stroke-width="1.5"/>';
$svg .= '<line x1="' . $padL . '" y1="' . ($padT + $plotH) . '" x2="' . ($padL + $plotW) . '" y2="' . ($padT + $plotH) . '" stroke="#333333" stroke-width="1.5"/>';
$svg .= '<text x="' . ($padL + $plotW / 2) . '" y="' . ($svgH - 8) . '" font-size="13" text-anchor="middle" fill="#222222">Class standing</text>';
$svg .= '<text x="14" y="' . ($padT + $plotH / 2) . '" font-size="13" text-anchor="middle" fill="#222222" transform="rotate(-90 14 ' . ($padT + $plotH / 2) . ')">Number of students</text>';
$svg .= '</svg>';

$anstypes = "number,number,choices";

$questions[0] = "";
$questions[1] = "";
$questions[2] = array(
  "The bars would all change height, so the graph would look different.",
  "The bars would keep the same relative heights, so the shape of the graph would be unchanged.",
  "The bars would all become the same height.",
  "The bars would reverse order from tallest to shortest."
);
$answer[0] = $total;
$answer[1] = $pickPct;
$answer[2] = 1;

// === QUESTION TEXT ===
<p>A survey asked every student in a statistics class to name their class standing. The bar graph below shows the <strong>counts</strong> in each category.</p>

<p>$svg</p>

<p>(a) How many students are in the class? $answerbox[0]</p>

<p>(b) What percentage of the class is in the <strong>$pickName</strong> category? Round to the nearest whole percent if needed. $answerbox[1] %</p>

<p>(c) Suppose the same data were drawn again as a bar graph of <strong>percentages</strong> instead of counts. What would happen to the shape of the graph?</p>

<p>$answerbox[2]</p>

// === ANSWER ===
$step1 = '<p><strong>Step 1 — Find the group size.</strong> Add the four bar heights: ' . $counts[0] . ' + ' . $counts[1] . ' + ' . $counts[2] . ' + ' . $counts[3] . ' = ' . $total . ' students.</p>';
$step2 = '<p><strong>Step 2 — Compute the percentage for ' . $pickName . '.</strong> Divide that category count by the total and multiply by 100: ' . $pickCount . ' / ' . $total . ' = ' . round($pickCount / $total, 4) . ', which is ' . $pickPct . '%. Because the total is ' . $total . ', each student is worth ' . round(100 / $total, 1) . ' of a percent, so the percentage is exact.</p>';
$step3 = '<p><strong>Step 3 — Why the shape does not change.</strong> Switching from counts to percentages divides every bar by the same total, ' . $total . '. Multiplying all the bar heights by one common factor rescales the vertical axis but leaves the bars in the same proportion to one another, so the tallest bar stays tallest and the graph keeps its shape. Only the axis labels change.</p>';
$step4 = '<p><strong>Answer:</strong> (a) ' . $total . ' students; (b) ' . $pickPct . '%; (c) the bars keep the same relative heights, so the shape is unchanged.</p>';
$solutionguide = $step1 . $step2 . $step3 . $step4;

// === NAME - DESCRIPTION:  ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
// Build a scatterplot with a roughly linear trend plus scatter, drawn as an SVG.
// Randomize: slope sign, strength of scatter, and the location of an outlier.

$slopeSign = rand(0,1);          // 0 = positive, 1 = negative
$slope = ($slopeSign == 0) ? rand(15,25)/10 : -rand(15,25)/10;   // 1.5 to 2.5 magnitude
