$solutionguide = '<p><b>Step 1 &mdash; Write the linear program.</b> Let `x` be the number of ' . $prod1 . ' and `y` the number of ' . $prod2 . '. Then</p>';
$solutionguide .= '<p>Maximize `P = ' . $p1 . 'x + ' . $p2 . 'y`</p>';
$solutionguide .= '<p>subject to</p>';
$solutionguide .= '<p>`' . $a11 . 'x + ' . $a12 . 'y <= ' . $b1 . '` &nbsp; (wax)</p>';
$solutionguide .= '<p>`' . $a21 . 'x + ' . $a22 . 'y <= ' . $b2 . '` &nbsp; (pour-table time)</p>';
$solutionguide .= '<p>`x >= 0, y >= 0`</p>';
$solutionguide .= '<p><b>Step 2 &mdash; Set up the initial simplex tableau.</b> Add slack variables `s_1` and `s_2`:</p>';
