$solutionguide .= '<p>`' . $a21 . 'x + ' . $a22 . 'y + s_2 = ' . $b2 . '`</p>';
$solutionguide .= '<p>`P - ' . $p1 . 'x - ' . $p2 . 'y = 0`</p>';
