$solutionguide .= '<p>`A^{-1} = (1/' . $detA . ') [[' . $adj[0][0] . ', ' . $adj[0][1] . ', ' . $adj[0][2] . '], [' . $adj[1][0] . ', ' . $adj[1][1] . ', ' . $adj[1][2] . '], [' . $adj[2][0] . ', ' . $adj[2][1] . ', ' . $adj[2][2] . ']]`</p>';
$solutionguide .= '<p>which is the matrix entered in part (a).</p>';
$solutionguide .= '<p><b>Step 3 &mdash; Multiply `A^{-1}` by `B`.</b></p>';
