$solutionguide .= '<p><b>Answer:</b> `A^{-1} = [[' . $AinvStr[0][0] . ', ' . $AinvStr[0][1] . ', ' . $AinvStr[0][2] . '], [' . $AinvStr[1][0] . ', ' . $AinvStr[1][1] . ', ' . $AinvStr[1][2] . '], [' . $AinvStr[2][0] . ', ' . $AinvStr[2][1] . ', ' . $AinvStr[2][2] . ']]` and `X = (' . $x0 . ', ' . $x1 . ', ' . $x2 . ')`.</p>';

