// === NAME - DESCRIPTION: Probability That a Sum Is Greater Than a Value - P(Sigma x > c): given a population mean, SD, and sample size, find the probability that the SUM of n observations exceeds a cutoff, using the sampling distribution of the sum ===
// === SET QUESTION TYPE TO: number ===

// === COMMON CONTROL ===
$mu = rand(20,80);
$sigma = rand(4,14);
$nList = array(9,12,16,20,25,30,36,49);
$n = $nList[rand(0,7)];
$cOffset = rand(1,6);
$c = $n*$mu + $cOffset*$sigma*sqrt($n);
$c = round($c,1);
$sumMean = $n*$mu;
$sumSD = $sigma*sqrt($n);
$sumSD = round($sumSD,3);
$z = ($c - $sumMean)/$sumSD;
$z = round($z,3);
loadlibrary("stats");
$p = 1 - normalcdf($z,0,1);
$answer = round($p,4);
$cDisp = prettyreal($c,1);
$sumMeanDisp = prettyreal($sumMean,1);
$sumSDDisp = prettyreal($sumSD,2);
$leftArea = round(1 - $p, 4);

// === QUESTION TEXT ===
<p>A certain population has mean `\mu = $mu` and standard deviation `\sigma = $sigma`.</p>

<p>A random sample of `n = $n` observations is taken from this population. Let `\Sigma x` denote the sum of the `n` observations.</p>

<p>Find the probability that the sum of the observations is greater than `$cDisp`. That is, find `P(\Sigma x > $cDisp)`.</p>

<p>Round your answer to 4 decimal places.</p>

<p>Probability = $answerbox</p>

// === ANSWER ===
$solutionguide = '<p><b>Step 1 &mdash; Find the mean and standard deviation of the sum.</b></p>';
$solutionguide .= '<p>For a sample of size `n` from a population with mean `\mu` and standard deviation `\sigma`, the sum `\Sigma x` has</p>';
$solutionguide .= '<p>`\mu_{\Sigma x} = n\mu = ' . $n . ' \cdot ' . $mu . ' = ' . $sumMeanDisp . '`</p>';
$solutionguide .= '<p>`\sigma_{\Sigma x} = \sqrt{n}\,\sigma = \sqrt{' . $n . '} \cdot ' . $sigma . ' = ' . $sumSDDisp . '`</p>';
$solutionguide .= '<p><b>Step 2 &mdash; Convert the cutoff to a z-score.</b></p>';
$solutionguide .= '<p>`z = \frac{\Sigma x - \mu_{\Sigma x}}{\sigma_{\Sigma x}} = \frac{' . $cDisp . ' - ' . $sumMeanDisp . '}{' . $sumSDDisp . '} = ' . $z . '`</p>';
$solutionguide .= '<p><b>Step 3 &mdash; Find the area to the right.</b></p>';
$solutionguide .= '<p>`P(\Sigma x > ' . $cDisp . ') = P(Z > ' . $z . ') = 1 - ' . $leftArea . ' = ' . $answer . '`</p>';
$solutionguide .= '<p>Answer: `' . $answer . '`</p>';

