// === NAME - DESCRIPTION: Write the slope-intercept equation of the line through two given points; accepts any equivalent form ===
// === SET QUESTION TYPE TO: numfunc ===

// === COMMON CONTROL ===
$x1 = rand(-6,6);
$x2 = rand(-6,6);
if ($x2 == $x1) { $x2 = $x1 + 1; if ($x2 > 6) { $x2 = $x1 - 1; } }
$y1 = rand(-8,8);
$y2 = rand(-8,8);
if ($y2 == $y1) { $y2 = $y1 + 1; if ($y2 > 8) { $y2 = $y1 - 1; } }

// slope as a reduced fraction
$num = $y2 - $y1;
$den = $x2 - $x1;
$g = gcd(abs($num), abs($den));
$mnum = $num / $g;
$mden = $den / $g;
if ($mden < 0) { $mnum = -$mnum; $mden = -$mden; }

// y-intercept: b = y1 - m*x1, exact fraction
$bnum = $y1 * $mden - $mnum * $x1;
$bden = $mden;
$gb = gcd(abs($bnum), abs($bden));
$bnum = $bnum / $gb;
$bden = $bden / $gb;
if ($bden < 0) { $bnum = -$bnum; $bden = -$bden; }

// display strings
if ($bden == 1) {
  if ($bnum < 0) { $bdisp = "- " . abs($bnum); } else { $bdisp = "+ " . $bnum; }
} else {
  if ($bnum < 0) { $bdisp = "- " . abs($bnum) . "/" . $bden; } else { $bdisp = "+ " . $bnum . "/" . $bden; }
}

// key: m*x + b as an expression string
if ($bden == 1) {
  $key = "($mnum/$mden)*x + ($bnum)";
} else {
  $key = "($mnum/$mden)*x + ($bnum/$bden)";
}

$answer = $key;
$answerbox = "y = ";

// === QUESTION TEXT ===
<p>Find the equation of the line that passes through the points `($x1, $y1)` and `($x2, $y2)`.</p>
<p>Write your answer in slope-intercept form, `y = mx + b`. You may enter the slope and intercept as fractions or decimals.</p>
<p>`y =` $answerbox</p>

// === ANSWER ===
$solutionguide = '<p>Step 1 — Find the slope.</p><p>`m = (y_2 - y_1)/(x_2 - x_1) = (' . $y2 . ' - ' . $y1 . ')/(' . $x2 . ' - ' . $x1 . ') = ' . $mnum . '/' . $mden . '`</p><p>Step 2 — Find the y-intercept using `y - y_1 = m(x - x_1)`.</p><p>Substituting `(' . $x1 . ', ' . $y1 . ')` gives `b = ' . $bnum . '/' . $bden . '`.</p><p>Step 3 — Write the equation.</p><p>Answer: `y = ' . $mnum . '/' . $mden . 'x ' . $bdisp . '`</p>';

// === NAME - DESCRIPTION: Identify whether a described study is an observational study or an experiment, typed as a word, accepting either capitalization ===
// === SET QUESTION TYPE TO: string ===

// === COMMON CONTROL ===
$scenarios = array(
  "A researcher records the resting heart rates of 40 volunteers and notes whether each volunteer reports exercising regularly.",
  "A researcher randomly assigns 60 volunteers to take a new supplement or a placebo for eight weeks, then compares their cholesterol levels.",
  "A researcher surveys 500 adults and asks how many hours they sleep each night and whether they own a pet.",
  "A researcher randomly assigns 30 plants to one of two fertilizers and later measures each plant's height.",
  "A researcher reviews hospital records to compare recovery times of patients who received two different treatments.",
  "A researcher randomly assigns 50 students to study with music or in silence, then compares their quiz scores.",
  "A researcher measures the arm span and height of 25 classmates to see whether the two are related.",
  "A researcher randomly assigns 80 patients to receive either a new drug or the standard drug, then records how long their symptoms last."
);
$isExp = array(false, true, false, true, false, true, false, true);
$pick = rand(0, 7);
$scenario = $scenarios[$pick];
$correct = $isExp[$pick] ? "experiment" : "observational study";
$strflags = "ignore_case,trim_whitespace";
$answer = "experiment or observational study";

// === QUESTION TEXT ===
<p>A study is described below. Determine whether it is an <b>observational study</b> or an <b>experiment</b>.</p>
<p>$scenario</p>
<p>This study is a(n): $answerbox</p>
<p>Type either <b>observational study</b> or <b>experiment</b>.</p>

// === ANSWER ===
$solutionguide = '<p>Step 1 &mdash; Look for a treatment imposed by the researcher. An experiment assigns a treatment to the subjects; an observational study only measures or records what is already there.</p><p>Step 2 &mdash; In this study, the researcher ' . ($isExp[$pick] ? 'randomly assigns a treatment to the subjects, so the researcher controls who gets which treatment.' : 'does not assign any treatment; the researcher simply measures or records information about the subjects as they are.') . '</p><p>Step 3 &mdash; Therefore this is an <b>' . $correct . '</b>.</p><p>Answer: ' . $correct . '</p>';

// === NAME - DESCRIPTION: Evaluate a(b - c)^2 for randomized integers a, b, c; assesses order of operations with a squared binomial and a negative factor ===
// === SET QUESTION TYPE TO: calculated ===

// === COMMON CONTROL ===
$a = randfrom(array(-5,-4,-3,-2,-1,1,2,3,4,5));
$b = randfrom(array(-6,-5,-4,-3,-2,-1,1,2,3,4,5,6));
$c = randfrom(array(-6,-5,-4,-3,-2,-1,1,2,3,4,5,6));
if ($b == $c) { $c = $c + 1; if ($c == 0) { $c = 2; } }
$diff = $b - $c;
$sq = $diff * $diff;
$answer = $a * $sq;
$bDisp = $b;
$cDisp = $c;
if ($c < 0) { $cDisp = "(" . $c . ")"; }
$diffDisp = $diff;
if ($diff < 0) { $diffDisp = "(" . $diff . ")"; }
$sqDisp = $sq;

// === QUESTION TEXT ===
<p>Evaluate the expression</p>
<p style="text-align:center">`$a($bDisp - $cDisp)^2`</p>
<p>Enter your answer as a single integer.</p>
<p>$answerbox</p>

// === ANSWER ===
$step1 = '<p><strong>Step 1 &mdash; Work inside the parentheses first.</strong> Subtract: `' . $bDisp . ' - ' . $cDisp . ' = ' . $diff . '`.</p>';
$step2 = '<p><strong>Step 2 &mdash; Apply the exponent.</strong> Square the result: `' . $diffDisp . '^2 = ' . $sq . '`.</p>';
$step3 = '<p><strong>Step 3 &mdash; Multiply by the factor in front.</strong> `' . $a . ' * ' . $sq . ' = ' . $answer . '`.</p>';
$step4 = '<p><strong>Answer:</strong> `' . $answer . '`</p>';
$solutionguide = $step1 . $step2 . $step3 . $step4;
